import numpy as np
from scipy.optimize import minimize
import os

N = 26; R_MIN = 1e-6; SAFETY = 1e-9
BASE_CENTERS_PATH = 'storage/Quest/n26_sota/centers.txt'
BASE_RADII_PATH = 'storage/Quest/n26_sota/radii.txt'
BETA_DISCOURAGE = 1e1; EPS_FAR = 0.01
TARGET_PAIR_DISCOURAGE = [(0, 5)]
SLSQP_JITTER_AMPLITUDES = [1e-4, 5e-4, 1e-3, 2e-3]
SLSQP_RESTARTS_PER_AMPLITUDE = 5

def cr_to_z(c, r): return np.concatenate([c.flatten(), r])
def z_to_cr(z): return z[:N*2].reshape(N, 2), z[N*2:]
def penalized_objective_discourage(z):
    c, r = z_to_cr(z)
    base_obj = -np.sum(r); penalty = 0.0
    for i, j in TARGET_PAIR_DISCOURAGE:
        dist = np.linalg.norm(c[i] - c[j])
        target_dist = r[i] + r[j] + EPS_FAR
        penalty += BETA_DISCOURAGE * max(0, target_dist - dist)**2
    return base_obj + penalty
def standard_objective(z): return -np.sum(z[N*2:])
def ineq_boundary(z):
    c, r = z_to_cr(z)
    return np.concatenate([c[:,0] - r, 1 - (c[:,0] + r), c[:,1] - r, 1 - (c[:,1] + r)])
def ineq_nonoverlap(z):
    c, r = z_to_cr(z)
    diff = c[:, None, :] - c[None, :, :]; dist = np.sqrt(np.sum(diff**2, axis=-1) + 1e-15)
    iu = np.triu_indices(N, 1); return dist[iu] - (r[iu[0]] + r[iu[1]])
def _ensure_validity(c, r):
    r_new = np.copy(r)
    for i in range(N): r_new[i] = min(r_new[i], c[i,0], 1-c[i,0], c[i,1], 1-c[i,1])
    for _ in range(10): 
        violations = 0
        for i in range(N):
            for j in range(i + 1, N):
                dist = np.linalg.norm(c[i] - c[j])
                if dist < r_new[i] + r_new[j]: 
                    violations+=1; scale = (dist/(r_new[i] + r_new[j]))*(1.0-SAFETY); r_new[i]*=scale; r_new[j]*=scale
        if violations == 0: break 
    return c, np.maximum(r_new, 0) 
def construct_packing() -> tuple:
    try: base_centers, base_radii = np.loadtxt(BASE_CENTERS_PATH), np.loadtxt(BASE_RADII_PATH)
    except: return np.random.rand(N,2), np.full(N, 0.05)
    initial_guess = cr_to_z(base_centers, base_radii)
    bounds = [(0,1)]*N*2 + [(R_MIN, 0.5)]*N
    constraints = [{'type': 'ineq', 'fun': ineq_boundary}, {'type': 'ineq', 'fun': ineq_nonoverlap}]
    discourage_res = minimize(penalized_objective_discourage, initial_guess, method='SLSQP', bounds=bounds, constraints=constraints, options={'maxiter': 500, 'ftol': 1e-10})
    if not discourage_res.success: return base_centers, base_radii
    discouraged_centers, discouraged_radii = z_to_cr(discourage_res.x)
    best_score = -np.inf; best_centers, best_radii = None, None
    for amp in SLSQP_JITTER_AMPLITUDES:
        for i in range(SLSQP_RESTARTS_PER_AMPLITUDE):
            np.random.seed(int(amp * 1e6) + i)
            jitter = np.random.uniform(-amp, amp, size=discouraged_centers.shape)
            perturbed_centers = np.clip(discouraged_centers + jitter, R_MIN, 1 - R_MIN)
            initial_z = cr_to_z(perturbed_centers, discouraged_radii)
            res = minimize(standard_objective, initial_z, method='SLSQP', bounds=bounds, constraints=constraints, options={'maxiter': 500, 'ftol': 1e-9})
            if res.success and -res.fun > best_score:
                best_score = -res.fun; c_res, r_res = z_to_cr(res.x); best_centers, best_radii = _ensure_validity(c_res, r_res)
    if best_centers is None: return discouraged_centers, discouraged_radii
    return best_centers, best_radii
